<script setup lang="ts">
import { onMounted, ref, watch } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import PageHeader from "@/components/PageHeader.vue";
import { ApiError } from "@/services/http";
import { createTarjeta,getTarjetaOptions,listTarjetas,updateTarjeta,type Tarjeta,type TarjetaOptions,type TarjetaPayload } from "@/services/tarjetas";

const items=ref<Tarjeta[]>([]);const options=ref<TarjetaOptions>({estadosTarjeta:[],tiposTarjeta:[],tiposVigencia:[],estadosAsignacion:[],beneficiarios:[],solicitudes:[]});const search=ref("");const page=ref(1);const pagination=ref({page:1,pageSize:10,total:0,totalPages:0});const loading=ref(false);const saving=ref(false);const error=ref("");const formError=ref("");const success=ref("");const editing=ref<Tarjeta|null>(null);const showForm=ref(false);const assignNow=ref(false);
const form=ref({codigoTarjeta:"",codigoExterno:"",numeroSerie:"",idEstadoTarjeta:0,idTipoTarjeta:null as number|null,fechaAdquisicion:"",fechaAlta:new Date().toISOString().slice(0,10),fechaBaja:"",motivoBaja:"",requiereRevision:false,observacionTarjeta:"",idSolicitud:0,idBeneficiario:0,idTipoVigencia:0,idEstadoAsignacion:0,fechaAsignacion:"",fechaInicioVigencia:"",fechaFinVigencia:"",numeroCompromiso:"",observacionEntrega:""});
const message=(value:unknown)=>value instanceof ApiError?value.message:"Ocurrió un error inesperado";
async function load(){loading.value=true;error.value="";try{const result=await listTarjetas(search.value,page.value);items.value=result.items;pagination.value=result.pagination;}catch(cause){error.value=message(cause);}finally{loading.value=false;}}
async function loadOptions(){try{options.value=await getTarjetaOptions();}catch(cause){error.value=message(cause);}}
function edit(item:Tarjeta|null){editing.value=item;formError.value="";assignNow.value=false;form.value={codigoTarjeta:item?.codigoTarjeta??"",codigoExterno:item?.codigoExterno??"",numeroSerie:item?.numeroSerie??"",idEstadoTarjeta:item?.idEstadoTarjeta??0,idTipoTarjeta:item?.idTipoTarjeta??null,fechaAdquisicion:item?.fechaAdquisicion?.slice(0,10)??"",fechaAlta:item?.fechaAlta?.slice(0,10)??new Date().toISOString().slice(0,10),fechaBaja:item?.fechaBaja?.slice(0,10)??"",motivoBaja:item?.motivoBaja??"",requiereRevision:item?.requiereRevision??false,observacionTarjeta:item?.observacionTarjeta??"",idSolicitud:item?.idSolicitud??0,idBeneficiario:item?.idBeneficiario??0,idTipoVigencia:0,idEstadoAsignacion:0,fechaAsignacion:"",fechaInicioVigencia:item?.fechaInicioVigencia?.slice(0,10)??"",fechaFinVigencia:item?.fechaFinVigencia?.slice(0,10)??"",numeroCompromiso:"",observacionEntrega:""};showForm.value=true;}
function asDate(value:string){return value?new Date(`${value}T00:00:00`):null;}
function payload():TarjetaPayload{return{codigoTarjeta:form.value.codigoTarjeta,codigoExterno:form.value.codigoExterno||null,numeroSerie:form.value.numeroSerie||null,idEstadoTarjeta:form.value.idEstadoTarjeta,idTipoTarjeta:form.value.idTipoTarjeta,fechaAdquisicion:asDate(form.value.fechaAdquisicion),fechaAlta:asDate(form.value.fechaAlta)!,fechaBaja:asDate(form.value.fechaBaja),motivoBaja:form.value.motivoBaja||null,requiereRevision:form.value.requiereRevision,observacionTarjeta:form.value.observacionTarjeta||null,assignment:assignNow.value?{idSolicitud:form.value.idSolicitud,idBeneficiario:form.value.idBeneficiario,idTipoVigencia:form.value.idTipoVigencia,idEstadoAsignacion:form.value.idEstadoAsignacion,fechaAsignacion:new Date(form.value.fechaAsignacion),fechaInicioVigencia:asDate(form.value.fechaInicioVigencia)!,fechaFinVigencia:asDate(form.value.fechaFinVigencia),numeroCompromiso:form.value.numeroCompromiso||null,observacionEntrega:form.value.observacionEntrega||null}:null};}
async function save(){formError.value="";saving.value=true;try{if(editing.value)await updateTarjeta(editing.value.idTarjeta,payload());else await createTarjeta(payload());showForm.value=false;success.value=editing.value?"Tarjeta actualizada correctamente.":"Tarjeta creada correctamente.";await load();}catch(cause){formError.value=message(cause);}finally{saving.value=false;}}
function changePage(next:number){page.value=next;void load();}watch(search,()=>{page.value=1;void load();});onMounted(()=>{void Promise.all([load(),loadOptions()]);});
</script>

<style scoped>
.tarjeta-primary,
.tarjeta-secondary {
  display: block;
}

.tarjeta-secondary {
  margin-top: 4px;
  color: #6b7a86;
  font-size: 11px;
  font-weight: 400;
}
</style>

<template>
  <AppBreadcrumb :items="[{label:'Administración',to:'/'},{label:'Operación'},{label:'Tarjetas'}]" />
  <PageHeader eyebrow="Operación" title="Tarjetas" description="Control del inventario de tarjetas y sus asignaciones operativas." action-label="Nueva tarjeta" @action="edit(null)" />
  <div v-if="success" class="bo-notice bo-notice-success">{{ success }}</div><div v-if="error" class="bo-state bo-state-error">{{ error }} <button class="bo-link" @click="load">Reintentar</button></div>
  <section class="bo-card"><form class="bo-toolbar" @submit.prevent="load"><input v-model="search" placeholder="Buscar por código, serie, beneficiario o solicitud..." aria-label="Buscar tarjetas" /><button class="bo-btn bo-btn-primary">Filtrar</button></form><div v-if="loading" class="bo-state">Cargando tarjetas...</div><div v-else-if="!items.length" class="bo-state"><strong>No hay tarjetas registradas.</strong><span>Cree una tarjeta para iniciar el inventario.</span></div><div v-else class="bo-table-wrap"><table><thead><tr><th>Tarjeta</th><th>Tipo</th><th>Beneficiario</th><th>Solicitud</th><th>Alta</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in items" :key="item.idTarjeta"><td><strong class="tarjeta-primary">{{ item.codigoTarjeta }}</strong><small class="tarjeta-secondary">{{ item.numeroSerie ?? item.codigoExterno ?? "Sin referencia adicional" }}</small></td><td>{{ item.nombreTipoTarjeta ?? "-" }}</td><td><span class="tarjeta-primary">{{ item.nombreBeneficiario ?? "Sin asignar" }}</span><small v-if="item.numeroCuenta" class="tarjeta-secondary">{{ item.numeroCuenta }}</small></td><td>{{ item.codigoSolicitud ?? "-" }}</td><td>{{ new Date(item.fechaAlta).toLocaleDateString("es-HN") }}</td><td><span class="status-badge" :class="{ 'status-badge--inactive': !item.estadoTarjeta }">{{ item.nombreEstadoTarjeta }}</span></td><td><button class="bo-action" @click="edit(item)">Editar</button></td></tr></tbody></table></div><footer v-if="!loading" class="bo-pagination"><span>{{ pagination.total }} registros · Página {{ pagination.page }} de {{ Math.max(pagination.totalPages,1) }}</span><div><button class="bo-page-button" :disabled="page<=1" @click="changePage(page-1)">Anterior</button><button class="bo-page-button" :disabled="page>=pagination.totalPages" @click="changePage(page+1)">Siguiente</button></div></footer></section>
  <div v-if="showForm" class="bo-modal-backdrop" @click.self="showForm=false"><section class="bo-modal"><header><div><span class="bo-eyebrow">{{ editing?"Editar registro":"Nuevo registro" }}</span><h2>{{ editing?"Editar tarjeta":"Crear tarjeta" }}</h2></div><button class="bo-close" type="button" @click="showForm=false">×</button></header><form class="bo-form" @submit.prevent="save"><div class="bo-form-grid"><label>Código de tarjeta *<input v-model="form.codigoTarjeta" maxlength="30" required /></label><label>Tipo de tarjeta<select v-model="form.idTipoTarjeta"><option :value="null">Sin tipo</option><option v-for="item in options.tiposTarjeta" :key="item.idTipoTarjeta" :value="item.idTipoTarjeta">{{ item.nombreTipoTarjeta }}</option></select></label><label>Código externo<input v-model="form.codigoExterno" maxlength="50" /></label><label>Número de serie<input v-model="form.numeroSerie" maxlength="100" /></label><label>Estado *<select v-model.number="form.idEstadoTarjeta" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.estadosTarjeta" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Fecha de alta *<input v-model="form.fechaAlta" type="date" required /></label><label>Fecha de adquisición<input v-model="form.fechaAdquisicion" type="date" /></label><label>Fecha de baja<input v-model="form.fechaBaja" type="date" /></label><label class="bo-form-wide">Motivo de baja<textarea v-model="form.motivoBaja" maxlength="500" rows="2" /></label><label class="bo-form-wide"><input v-model="form.requiereRevision" type="checkbox" /> Requiere revisión</label><label class="bo-form-wide">Observación<textarea v-model="form.observacionTarjeta" maxlength="1000" rows="2" /></label></div><div v-if="!editing" class="bo-assignment"><label class="bo-form-wide"><input v-model="assignNow" type="checkbox" /> Crear asignación ahora</label><div v-if="assignNow" class="bo-form-grid"><label>Solicitud *<select v-model.number="form.idSolicitud" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.solicitudes" :key="item.idSolicitud" :value="item.idSolicitud">{{ item.codigoSolicitud }} · {{ item.nombreBeneficiario }}</option></select></label><label>Beneficiario *<select v-model.number="form.idBeneficiario" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.beneficiarios" :key="item.idBeneficiario" :value="item.idBeneficiario">{{ item.nombreBeneficiario }} · {{ item.numeroCuenta ?? "Sin cuenta" }}</option></select></label><label>Vigencia *<select v-model.number="form.idTipoVigencia" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.tiposVigencia" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Estado de asignación *<select v-model.number="form.idEstadoAsignacion" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.estadosAsignacion" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Fecha de asignación *<input v-model="form.fechaAsignacion" type="datetime-local" required /></label><label>Inicio de vigencia *<input v-model="form.fechaInicioVigencia" type="date" required /></label><label>Fin de vigencia<input v-model="form.fechaFinVigencia" type="date" /></label><label>Número de compromiso<input v-model="form.numeroCompromiso" maxlength="50" /></label><label class="bo-form-wide">Observación de entrega<textarea v-model="form.observacionEntrega" maxlength="1000" rows="2" /></label></div></div><p v-if="formError" class="bo-form-error">{{ formError }}</p><footer><button class="bo-btn" type="button" @click="showForm=false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="saving">{{ saving?"Guardando...":"Guardar" }}</button></footer></form></section></div>
</template>
